pair<int,int> topTwo(const vector<int>& a) {
    int best = INT_MIN, second = INT_MIN;
    for (int x : a) {
        if (x > best) {          // new king; old king is demoted
            second = best;
            best = x;
        } else if (x > second && x < best) {
            second = x;          // new runner-up only; equal values do not count
        }
    }
    return {best, second};
}

