def top_two(a: list[int]) -> tuple[int, int]:
    best = second = float('-inf')
    for x in a:
        if x > best:             # new king; old king is demoted
            best, second = x, best
        elif second < x < best:
            second = x           # new runner-up only; equal values do not count
    return (best, second)

