int firstDuplicateNaive(const vector<int>& a) {
    for (size_t i = 0; i < a.size(); ++i)
        for (size_t j = 0; j < i; ++j)
            if (a[j] == a[i]) return a[i];
    return -1;
}

// Set: ask before inserting; the first YES is the answer
int firstDuplicate(const vector<int>& a) {
    unordered_set<int> seen;
    for (int x : a) {
        if (seen.count(x)) return x;
        seen.insert(x);
    }
    return -1;
}

