vector<int> topK(const vector<int>& a, int k) {
    priority_queue<int> pq(a.begin(), a.end());   // heapify: O(n), not O(n log n)
    vector<int> out;
    for (int i = 0; i < k && !pq.empty(); ++i) {
        out.push_back(pq.top());                  // current biggest
        pq.pop();
    }
    return out;
}

map<string,int> wordFrequency(const vector<string>& words) {
    map<string,int> freq;
    for (const string& w : words)
        ++freq[w];        // creates with value 0 then increments, in one step
    return freq;          // iterating a std::map yields keys in sorted order
}

